class Solution {
public:
    long long pascalElement(int r, int c) {
        // (r-1 choose c-1)
        int n = r - 1;
        int k = c - 1;
        if (k < 0 || k > n) return 0;
        if (k > n - k) k = n - k;
        long long res = 1;
        for (int i = 1; i <= k; ++i) {
            res = res * (n - k + i) / i;
        }
        return res;
    }
};
